sparql:
PREFIX ex: <https://w3id.org/evqa/seed#>
PREFIX d: <https://w3id.org/evqa/data/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX qudt: <http://qudt.org/schema/qudt/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?r ?paper ?subject ?context ?contextLabel ?dose ?week ?value ?unit WHERE {
  VALUES ?subject { d:quendarin }
  ?r a ex:Result ;
     ex:subject ?subject ;
     ex:reportedIn ?paper ;
     ex:comparator d:placebo ;
     sosa:observedProperty d:hba1c-change ;
     sosa:hasFeatureOfInterest ?context ;
     ex:statistic ex:MeanDifference ;
     ex:condition/ex:setting/qudt:numericValue ?dose ;
     ex:atTime/qudt:numericValue ?week ;
     sosa:hasResult [ qudt:numericValue ?value ; qudt:unit ?unit ] .
  ?paper ex:split "test" .
  ?context skos:prefLabel ?contextLabel .
  FILTER(?week = 52)
} ORDER BY ?subject ?context ?dose ?week ?r
